INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(44632120, 'Kuribah', '栗子丸', 'クリバー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名在规则上也当作「栗子球」卡使用。这个卡名的①的效果1回合只能使用1次。 ①：这张卡或者自己的「栗子球」怪兽被战斗破坏时才能发动。从卡组把「栗子丸」以外的1只攻击力300/守备力200的怪兽特殊召唤。 ②：把场上的这张卡和自己的手卡·场上的「栗子团」「栗子圆」「栗子珠」「栗子球」各1只解放才能发动。从自己的手卡·卡组·墓地选1只「巴比伦栗子」特殊召唤。'),
(16404809, 'Kuribandit', '库里盗贼', 'クリバンデット', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 700, '①：这张卡召唤的回合的结束阶段，把这张卡解放才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1张魔法·陷阱卡加入手卡。剩下的卡送去墓地。'),
(71036835, 'Kuribee', '栗子团', 'クリビー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名在规则上也当作「栗子球」卡使用。这个卡名的①的效果1回合只能使用1次。 ①：这张卡或者自己的「栗子球」怪兽被战斗破坏时才能发动。从卡组把有「栗子球」的卡名记述的1张魔法·陷阱卡加入手卡。 ②：1回合1次，自己场上有其他的「栗子球」怪兽存在的场合，对方怪兽的攻击宣言时才能发动。这张卡以外的自己场上的全部怪兽的攻击力直到回合结束时变成0，那次攻击无效。'),
(34419588, 'Kuribeh', '栗子珠', 'クリベー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名在规则上也当作「栗子球」卡使用。 ①：把这张卡从手卡丢弃，以自己场上1只「栗子球」怪兽为对象才能发动。那只怪兽的攻击力上升1500。这个效果在对方回合也能发动。 ②：把场上的这张卡和自己的手卡·场上的「栗子丸」「栗子团」「栗子圆」「栗子球」各1只解放才能发动。从自己的卡组·墓地选1只「盗贼栗子」加入手卡。那之后，可以从手卡把1只恶魔族怪兽召唤。'),
(40640057, 'Kuriboh', '库里波', 'クリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '①：对方怪兽的攻击要让自己受到战斗伤害的伤害计算时，把这张卡从手卡丢弃才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(40703223, 'Kuriboh Token', '增殖', '増殖', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(78355370, 'Kuribohrn', '苏生栗子球', 'クリボーン', 'Effect Monster', 'Fiend', 'LIGHT', 1, 300, 200, '①：自己·对方的战斗阶段结束时把这张卡从手卡丢弃，以这个回合被战斗破坏送去自己墓地的1只怪兽为对象才能发动。那只怪兽特殊召唤。 ②：对方怪兽的攻击宣言时，把墓地的这张卡除外，以自己墓地的「栗子球」怪兽任意数量为对象才能发动。那些怪兽特殊召唤。'),
(47432275, 'Kuribon', '缎带栗子', 'クリボン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 300, 200, '这张卡成为对方怪兽的攻击对象的战斗伤害计算时，可以把那次战斗发生的对自己的战斗伤害变成0并让对方基本分回复攻击怪兽的攻击力的数值，这张卡回到手卡。'),
(34873741, 'Kuribon the Fairy Spirit', '妖精灵 库里缎带', '妖精霊クリボン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「古代妖精龙」或者兽族·植物族·天使族的光属性怪兽的其中任意种存在的场合才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡当作调整使用。 ②：自己场上的其他的「古代妖精龙」或者有那个卡名记述的怪兽被效果破坏的场合，可以作为代替让场上的这张卡回到手卡。'),
(7021574, 'Kuriboo', '栗子圆', 'クリブー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名在规则上也当作「栗子球」卡使用。 ①：对方怪兽的攻击宣言时把这张卡从手卡丢弃才能发动。从卡组把「栗子圆」以外的1只「栗子球」怪兽加入手卡。 ②：1回合1次，从手卡丢弃1张陷阱卡，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降1500。这个效果在对方回合也能发动。'),
(35405755, 'Kurikara Divincarnate', '俱利伽罗天童', '俱利伽羅天童', 'Effect Monster', 'Fairy', 'FIRE', 1, 1500, 1500, '这张卡不能通常召唤。把这个回合有在对方的怪兽区域把效果发动过的自己·对方场上的表侧表示怪兽全部解放的场合才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升因为这张卡特殊召唤而解放的怪兽数量×1500。 ②：自己结束阶段，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(66102515, 'Kurikurinku @Ignister', '库里库连接＠伊格尼斯者', 'クリクリンク＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把自己场上1只「@火灵天星」怪兽解放才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：从额外卡组特殊召唤的电子界族怪兽在自己场上存在，自己场上的电子界族怪兽为对象的效果发动时，把这张卡解放才能发动。那个效果无效。'),
(35112613, 'Kuriphoton', '库里光子', 'クリフォトン', 'Effect Monster', 'Fiend', 'LIGHT', 1, 300, 200, '这个卡名的②的效果1回合只能使用1次。 ①：把这张卡从手卡送去墓地，支付2000基本分才能发动。这个回合，自己受到的全部伤害变成0。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的场合，从手卡把「光子栗子」以外的1只「光子」怪兽送去墓地才能发动。墓地的这张卡加入手卡。'),
(40817915, 'Kurivolt', '电击栗子', 'クリボルト', 'Effect Monster', 'Thunder', 'LIGHT', 1, 300, 200, '自己的主要阶段时，选择持有超量素材的1只超量怪兽才能发动。把选择的怪兽1个超量素材取除，从自己卡组把1只「电击栗子」特殊召唤。这张卡不能作为同调素材。'),
(77511331, 'Kuro-Obi Karate Spirit', '空手魂 黑带', 'カラテ魂 KURO－OBI', 'Spirit Monster', 'Warrior', 'WIND', 5, 2400, 1000, '①：这张卡召唤成功时才能发动。和自己的灵摆区域的卡相同纵列的对方的魔法·陷阱卡全部送去墓地。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(60802233, 'Kuwagata α', '锹甲阿尔法', 'クワガタ・アルファ', 'Normal Monster', 'Insect', 'EARTH', 4, 1250, 1000, '凶暴的锹甲。要注意直取对方首级的断头切割。'),
(95144193, 'Kwagar Hercules', '锹形海克力士', 'クワガー・ヘラクレス', 'Fusion Monster', 'Insect', 'EARTH', 6, 1900, 1700, '「锹甲阿尔法」＋「大力独角仙」'),
(88240808, 'Kycoo the Ghost Destroyer', '灵灭术师 海空', '霊滅術師 カイクウ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 700, '①：只要这张卡在怪兽区域存在，对方不能把双方墓地的卡除外。 ②：这张卡给与对方战斗伤害时，以对方墓地最多2只怪兽为对象才能发动。那些怪兽除外。'),
(93509766, 'Kyoro Ryu-Ge Kaiva', '恐巄龙华－㟴轮巴王', '恐巄竜華－㟴巴', 'Effect Monster', 'Dinosaur', 'EARTH', 10, 3000, 1200, '这个卡名的①②③的效果1回合各能使用1次。 ①：让这张卡从手卡回到卡组才能发动。从卡组把1张「登龙华恐巃门」加入手卡。 ②：2张以上的卡被破坏的回合的自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。 ③：让自己场上1张表侧表示的「登龙华恐巃门」回到卡组最下面，以最多有场上的种族种类数量的场上的其他卡为对象才能发动。那些卡破坏。'),
(56111151, 'Kyoutou Waterfront', '惊塔海滨', 'KYOUTOUウォーターフロント', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次场上的卡被送去墓地，每有1张给这张卡放置1个坏兽指示物（最多5个）。 ②：1回合1次，这张卡的坏兽指示物是3个以上的场合才能发动。自己从卡组把1只「坏兽」怪兽加入手卡。 ③：这张卡被效果破坏的场合，可以作为代替把这张卡1个坏兽指示物取除。'),
(47028805, 'L Magi Mergy', '码集小魔吉', 'Lマジマージ', 'Effect Monster', 'Cyberse', 'DARK', 2, NULL, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，这张卡在手卡存在的场合，把自己场上1只电子界族怪兽或连接怪兽解放才能发动。这张卡特殊召唤。 ②：这张卡的攻击力上升自己墓地的连接怪兽的连接标记合计×400。'),
(97590747, 'La Jinn the Mystical Genie of the Lamp', '灯之魔精', 'ランプの魔精・ラ・ジーン', 'Normal Monster', 'Fiend', 'DARK', 4, 1800, 1000, '凡是出自呼唤他的主人之口，任何要求都听从的灯之精灵。'),
(62514770, 'Labradorite Dragon', '拉长石龙', 'ラブラドライドラゴン', 'Normal Tuner Monster', 'Dragon', 'DARK', 6, NULL, 2400, '身上鳞片发出称为拉长石晕彩这一特有美丽光辉的龙。那鳞片中产生的耀眼光辉，具有引导观看者灵魂，令其解放内心情感的力量。 ——它的光芒相传会追溯前世的记忆，引起人们的相遇。'),
(48745395, 'Labrynth Archfiend', '拉比丽斯的恶魔像', '白銀の城の魔神像', 'Effect Monster', 'Fiend', 'DARK', 7, 2000, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：陷阱卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组选只在攻击宣言时才能作卡的发动的1张通常陷阱卡在自己场上盖放。 ③：这张卡的攻击力上升自己墓地的通常陷阱卡种类×400，对方不能选择「白银之城的魔神像」以外的恶魔族怪兽作为攻击对象。'),
(68779682, 'Labrynth Barrage', '拉比丽斯・连环计', 'ラビュリンス・バラージュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：「拉比林斯迷宫连环阵」以外的盖放的通常陷阱卡由自己发动时才能发动。这张卡的效果变成和那张通常陷阱卡发动时的效果相同。这张卡的发动后，直到下个对方回合的结束时自己的效果发生的对对方的效果伤害变成0。'),
(37629703, 'Labrynth Chandraglier', '拉比丽斯的龙饰灯', '白銀の城の竜飾灯', 'Effect Monster', 'Fiend', 'DARK', 3, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地，丢弃1张手卡才能发动。从手卡·卡组选1张「拉比林斯迷宫」魔法·陷阱卡在自己场上盖放。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的状态，自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。这张卡加入手卡。'),
(2511, 'Labrynth Cooclock', '拉比丽斯的疯时钟', '白銀の城の狂時計', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。这个回合，自己场上有「拉比林斯迷宫」怪兽存在的场合，自己可以把1张通常陷阱卡在盖放的回合发动。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的状态，为让自己把「白银之城的狂时钟」以外的「拉比林斯迷宫」卡的效果或者通常陷阱卡发动而让手卡的卡被送去墓地的场合才能发动。这张卡加入手卡或特殊召唤。'),
(33407125, 'Labrynth Labyrinth', '白银的迷宫城・拉比丽斯', '白銀の迷宮城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：盖放的「拉比林斯迷宫欢迎」通常陷阱卡由自己发动的场合，可以给那个效果加上以下效果。 ●选场上1张卡破坏。 ②：自己把「拉比林斯迷宫」卡以外的通常陷阱卡发动的场合才能发动。从自己的手卡·墓地选1只恶魔族怪兽特殊召唤。'),
(69895264, 'Labrynth Set-Up', '拉比丽斯・设置', 'ラビュリンス・セッティング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地的卡以及除外的自己的卡之中以「拉比林斯迷宫布置」以外的2张「拉比林斯迷宫」魔法·陷阱卡为对象才能发动。那些卡回到卡组。并且，自己场上有恶魔族怪兽存在的场合，可以再从卡组选回去数量的「拉比林斯迷宫」卡以外的通常陷阱卡在自己场上盖放（同名卡最多1张）。'),
(74018812, 'Labrynth Stovie Torbie', '拉比丽斯的吹火炉', '白銀の城の火吹炉', 'Effect Monster', 'Fiend', 'DARK', 2, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地，丢弃1张手卡才能发动。从手卡·卡组选1张「拉比林斯迷宫」魔法·陷阱卡在自己场上盖放。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的状态，自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。这张卡特殊召唤。'),
(35026117, 'Labyrinth Heavy Tank', '迷宫的重魔战车', '迷宮の重魔戦車', 'Effect Monster', 'Machine', 'DARK', 7, 2400, 2400, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以不用解放作召唤。 ②：这张卡在召唤的回合不能攻击。 ③：自己主要阶段才能发动。选自己的手卡·卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。自己场上有「迷宫壁」卡存在的场合，可以再把对方场上1只怪兽破坏。'),
(66526672, 'Labyrinth of Nightmare', '噩梦之迷宫', '悪夢の迷宮', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '在每1个回合的结束阶段时，变更该回合行动玩家场上所有以表侧表示存在的怪兽的表示形式。'),
(99551425, 'Labyrinth Tank', '迷宫的魔战车', '迷宮の魔戦車', 'Fusion Monster', 'Machine', 'DARK', 7, 2400, 2400, '「高科技狼」＋「加农炮兵」'),
(67284908, 'Labyrinth Wall', '迷宫壁', '迷宮壁－ラビリンス・ウォール－', 'Normal Monster', 'Rock', 'EARTH', 5, NULL, 3000, '出现结界般的厚壁，制造出没有出口的迷宫。'),
(34771947, 'Labyrinth Wall Shadow', '迷宫壁・影', 'ラビリンス・ウォール・シャドウ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：除原本等级是5星以上的怪兽外的召唤·反转召唤·特殊召唤的怪兽在那个回合不能攻击。 ②：1回合1次，自己主要阶段才能发动。选自己的手卡·卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ③：对方战斗阶段开始时，以对方场上1只攻击力未满1600的怪兽为对象才能发动。那只怪兽破坏。'),
(28803166, 'Lacrima the Crimson Tears', '红泪之魔 拉克莉末莎', '紅涙の魔ラクリモーサ', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1200, 1200, '这个卡名在规则上也当作「刻魔」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「红泪之魔 落泪之日」以外的1张「刻魔」卡送去墓地。 ②：对方回合，这张卡在墓地存在的场合，以自己墓地1只「刻魔」连接怪兽为对象才能发动。这张卡回到卡组，作为对象的怪兽特殊召唤。'),
(90147755, 'Lady Assailant of Flames', '炎之女暗杀者', '炎の女暗殺者', 'Flip Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1000, '反转：自己的卡组最上面的3张卡在游戏中除外。对方受到800分的伤害。'),
(16188701, 'Lady Debug', '瓢虫调试员', 'レディ・デバッガー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1700, 1400, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只3星以下的电子界族怪兽加入手卡。'),
(81497285, 'Lady Labrynth of the Silver Castle', '迷宫城的白银姬・拉比丽斯', '迷宮城の白銀姫', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 2900, '这个卡名的①③的效果1回合各能使用1次。 ①：「迷宫城的白银姬」以外的「拉比林斯迷宫」卡的效果或者通常陷阱卡发动的自己·对方回合才能发动。这张卡从手卡守备表示特殊召唤。 ②：只要自己场上有里侧表示卡存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ③：通常陷阱卡发动时才能发动。和那张卡卡名不同的1张通常陷阱卡从卡组到自己场上盖放。'),
(82005435, 'Lady Ninja Yae', '女忍者 八重', '女忍者ヤエ', 'Effect Monster', 'Warrior', 'WIND', 3, 1100, 200, '从手卡将1张风属性怪兽卡弃到墓地。将对方场上存在的所有魔法·陷阱卡全部弹回其持有者手卡。'),
(67511500, 'Lady of D.', '龙魔女-龙之守护者-', 'ドラゴン・ウィッチ－ドラゴンの守護者－', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1100, '只要这张卡在场上表侧表示存在，对方不能选择自己场上的龙族怪兽作为攻击对象。场上的这张卡被战斗或者卡的效果破坏的场合，可以作为代替从手卡把1只龙族怪兽送去墓地。'),
(17358176, 'Lady of Faith', '高等女祭司', 'ハイ・プリーステス', 'Normal Monster', 'Spellcaster', 'LIGHT', 3, 1100, 800, '咏唱起闻所未闻的咒语，使所有人的心平静下来。'),
(10736540, 'Lady of the Lake', '湖中少女 薇薇安', '湖の乙女ヴィヴィアン', 'Tuner Monster', 'Aqua', 'LIGHT', 1, 200, 1800, '把这张卡作为同调素材的场合，不是战士族怪兽的同调召唤不能使用，被同调召唤使用的这张卡除外。 ①：这张卡召唤成功时，以自己墓地1只「圣骑士」通常怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在墓地存在的场合，以自己场上1只5星「圣骑士」怪兽为对象才能发动。那只怪兽的等级下降1星，这张卡从墓地特殊召唤。'),
(38480590, 'Lady Panther', '女豹佣兵', '女豹の傭兵', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1400, 1300, '表侧表示的这张卡做祭品。1只这个回合被战斗破坏送去墓地的自己的怪兽回到卡组的最上面。'),
(48658295, 'Lady''s Dragonmaid', '龙女仆・服侍龙女', 'ドラゴンメイド・ラティス', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2000, 3000, '相同属性而等级不同的「半龙女仆」怪兽×2 从自己的场上以及墓地各把1只上记的卡除外的场合才能从额外卡组特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1只4星以下的「半龙女仆」怪兽特殊召唤。 ②：自己·对方的准备阶段才能发动。自己的场上·除外状态的怪兽作为融合素材回到卡组，把1只龙族融合怪兽融合召唤。'),
(74615388, 'Laevatein, Generaider Boss of Shadows', '影之创王 雷万汀', '影の王 レイヴァーテイン', 'XYZ Monster', 'Fairy', 'FIRE', 9, 2500, 2500, '9星怪兽×2只以上 ①：「影界王战 雷瓦汀王」在自己场上只能有1只表侧表示存在。 ②：对方场上的怪兽的攻击力·守备力下降1000。 ③：自己·对方回合，把超量召唤的这张卡解放才能发动。从额外卡组把天使族怪兽以外的1只「王战」超量怪兽特殊召唤。那之后，可以选最多有这张卡持有的超量素材数量的自己或者对方的场上·墓地的卡在这个效果特殊召唤的怪兽下面重叠作为超量素材。'),
(6260560, 'Laevateinn the Burning Blade', '炎魔刃 雷瓦汀', '炎魔刃レーヴァテイン', 'Link Monster', 'Warrior', 'FIRE', NULL, 1000, NULL, '炎属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把自己场上1只其他的炎属性怪兽解放，以原本等级比那只怪兽低并原本种族相同的自己墓地1只炎属性怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：自己的魔法与陷阱区域的里侧表示卡被对方的效果破坏的场合，可以作为代替把场上的这张卡除外。'),
(53904087, 'Lahamu the Messenger of Sacred Scripture', NULL, NULL, 'Link Monster', 'Fairy', 'DARK', NULL, 1400, NULL, NULL),
(59160188, 'Lair of Darkness', '暗黑世界－暗影恶托邦', '闇黒世界－シャドウ・ディストピア－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的表侧表示怪兽变成暗属性。 ②：1回合1次，自己为让卡的效果发动而把自己场上的怪兽解放的场合，可以作为自己场上1只怪兽的代替而把对方场上1只暗属性怪兽解放。 ③：自己·对方的结束阶段发动。把最多有这个回合这张卡表侧表示存在的状态被解放的怪兽数量的「暗影衍生物」（恶魔族·暗·3星·攻/守1000）在回合玩家的场上尽可能守备表示特殊召唤。'),
(81128478, 'Lair Wire', '蛛穴丝网', 'ライヤー・ワイヤー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地存在的1只昆虫族怪兽从游戏中除外，选择对方场上存在的1只怪兽发动。选择的怪兽破坏。'),
(9430387, 'LaLa Li-oon', '雷云怪', 'ララ・ライウーン', 'Normal Monster', 'Thunder', 'WIND', 2, 600, 600, '带电的云形怪兽。下着能溶掉一切的危险之雨。'),
(60764582, 'Lamb Token', '迷途的羔羊', '迷える仔羊', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(84900597, 'Lamia', '拉米亚', 'ラミア', 'Effect Monster', 'Reptile', 'DARK', 4, 1300, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只爬虫类族·8星怪兽加入手卡。 ②：这张卡被除外的场合，以自己场上1只爬虫类族怪兽为对象才能发动。那只怪兽直到下个回合的结束时不会被效果破坏。'),
(75850803, 'LaMoon', '明月', 'ラムーン', 'Normal Monster', 'Spellcaster', 'LIGHT', 5, 1200, 1700, '住在月亮上的魔法师。用月之魔力迷惑对方。'),
(96402918, 'Lancea, Ancestral Dragon of the Ice Mountain', '冰灵山龙祖 矛枪龙', '氷霊山の龍祖 ランセア', 'Synchro Monster', 'Dragon', 'WATER', 10, 3300, 2700, '水属性调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合可以使用最多2次。 ①：对方把怪兽特殊召唤的场合才能发动（同一连锁上最多1次）。从自己的手卡·卡组·额外卡组·墓地把1只「冰结界」怪兽特殊召唤。那之后，可以把对方场上1只攻击表示怪兽变成守备表示。 ②：同调召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。从额外卡组把1只「冰结界」同调怪兽当作同调召唤作特殊召唤。'),
(48940337, 'Lancephorhynchus', '枪头喙嘴龙', 'ランスフォリンクス', 'Pendulum Normal Monster', 'Dinosaur', 'WIND', 6, 2500, 800, '太古灭绝之下幸存的梦幻翼龙。它的模样进化得更有攻击性，尖喙化成了贯穿一切的长枪。尽管如此主食好像还是吃鱼。'),
(79418153, 'Lancer Archfiend', '枪兵恶魔', 'ランサー・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1400, '对方场上守备表示存在的怪兽为攻击对象的自己怪兽的攻击宣言时才能发动。那只怪兽向守备表示怪兽攻击的场合，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这个效果1回合只能使用1次。'),
(11125718, 'Lancer Dragonute', '枪兵龙人', 'ランサー・ドラゴニュート', 'Effect Monster', 'Dragon', 'DARK', 4, 1500, 1800, '①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(46272804, 'Lancer Lindwurm', '长枪鳞虫', 'ランス・リンドブルム', 'Effect Monster', 'Dragon', 'WIND', 4, 1800, 1200, '①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(61264008, 'Land Flipping', '炒土地', '土地ころがし', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己或者对方的场地区域1张表侧表示的卡为对象才能发动。那张卡除外。那之后，这个效果除外的卡在从被除外的玩家来看的对方的场地区域表侧表示放置。那之后，可以从被放置的玩家的墓地选原本卡名和放置的卡不同的1张场地魔法卡在被这个效果把卡除外的玩家的场地区域表侧表示放置。'),
(300302033, 'Land of the Ojamas (Skill Card)', NULL, NULL, 'Skill Card', 'Chazz Princet', NULL, NULL, NULL, NULL, NULL),
(74717840, 'Landoise''s Luminous Moss', '地龟的光藓', 'ランドオルスのヒカリゴケ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「自然」的怪兽表侧表示存在的场合才能发动。这个回合，对方的效果怪兽不能把效果发动。'),
(95993388, 'Landrobe the Rock Vassal', '地帝家臣兰德罗布', '地帝家臣ランドローブ', 'Effect Monster', 'Rock', 'EARTH', 4, 800, 1000, '「地帝家臣 兰罗布」的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽变成里侧守备表示。这个回合，自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡为上级召唤而被解放的场合，以「地帝家臣 兰罗布」以外的自己墓地1只攻击力800/守备力1000的怪兽为对象才能发动。那只怪兽加入手卡。'),
(77637979, 'LANphorhynchus', '局域网喙嘴龙', 'LANフォリンクス', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1200, NULL, '怪兽2只'),
(70156946, 'Lantern Shark', '灯笼鲨', 'ランタン・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 900, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡把「提灯鲨」以外的1只3～5星的水属性怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：把这张卡在水属性怪兽的超量召唤使用的场合，可以把这张卡的等级当作3星或5星使用。'),
(3111207, 'Lappis Dragon', '彩宝龙', '彩宝龍', 'Tuner Monster', 'Sea Serpent', 'WATER', 5, NULL, 2600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡从卡组加入手卡的场合，把这张卡给对方观看才能发动。这张卡特殊召唤。 ②：这张卡因效果从自己墓地加入手卡的场合，把这张卡给对方观看才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(87756343, 'Larvae Moth', '飞蛾幼虫', 'ラーバモス', 'Effect Monster', 'Insect', 'EARTH', 2, 500, 400, '这张卡不能通常召唤。需要装备了「进化之茧」2回合（数自己的回合数）的「飞蛾宝宝」做祭品特殊召唤上场。'),
(94675535, 'Larvas', '拉瓦斯', 'ラーバス', 'Normal Monster', 'Beast', 'EARTH', 3, 800, 1000, '行动速度飞快的鸟怪，用细长的手腕将敌人绞杀。'),
(77007920, 'Laser Cannon Armor', '镭射炮机甲铠', 'レーザー砲機甲鎧', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '昆虫族怪兽才能装备。装备怪兽的攻击力·守备力上升300。'),
(43034264, 'Laser Qlip', '机壳的要塞', '機殻の要塞', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「机壳」怪兽召唤。 ②：只要这张卡在场地区域存在，「机壳」怪兽的召唤不会被无效化。'),
(27993919, 'LaSolfachord Angelia', '拉音服和弦・安吉莉娅', 'ラドレミコード・エンジェリア', 'Pendulum Effect Monster', 'Fairy', 'FIRE', 6, 2300, 1400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己场上1只「七音服」灵摆怪兽解放，比那只怪兽灵摆刻度高2或者低2的「拉之七音服·安琪莉娅」以外的1只「七音服」灵摆怪兽从卡组特殊召唤。 ②：自己的灵摆区域有奇数的灵摆刻度存在，自己的「七音服」灵摆怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡的效果不能发动。'),
(66970385, 'Last Chapter of the Noble Knights', '圣骑士传说的终幕', '聖騎士伝説の終幕', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「圣骑士传说的终幕」在1回合只能发动1张。 ①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，以自己墓地1只「圣骑士」怪兽和1张那只怪兽可以装备的「圣剑」装备魔法卡为对象才能发动。那只怪兽特殊召唤，那张装备魔法卡给作为正确对象的那只怪兽装备。'),
(86049351, 'Last Counter', '最终反击', 'ラスト・カウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上的名字带有「燃烧拳击手」的怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那次攻击无效，那只自己怪兽送去墓地。自己场上1只名字带有「燃烧拳击手」的怪兽的攻击力上升那只对方怪兽的原本攻击力数值，和那只对方怪兽进行伤害计算。那之后，自己受到这张卡的效果上升的攻击力数值的伤害。'),
(90330453, 'Last Day of Witch', '魔女狩猎', '魔女狩り', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示的魔法师族的怪兽全部破坏。'),
(300202005, 'Last Gamble', NULL, NULL, 'Skill Card', 'Joey', NULL, NULL, NULL, NULL, NULL),
(50847759, 'Last Hope of Nephthys', '奈芙蒂斯的希望', 'ネフティスの希望', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1张「奈芙提斯」卡和对方场上1张卡为对象才能发动。那些卡破坏。'),
(95254840, 'Last Minute Cancel', '临时取消', 'ドタキャン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。自己场上的怪兽全部变成守备表示。这张卡的发动后，直到回合结束时被战斗·效果破坏的自己场上的表侧表示的「娱乐伙伴」怪兽不去墓地回到持有者手卡。'),
(97970833, 'Last Resort', '最后胜地', 'ラスト・リゾート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。从自己卡组选择1张「虹之古代都市」发动。这个时候，对方的场地魔法在发动的场合，对方玩家可以抽1张卡。'),
(28566710, 'Last Turn', '最终一战！', 'ラストバトル！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的基本分1000分以下时，在对方的回合才能发动。选择自己的场上的1只怪兽，双方的其他的场上和手上的卡全部送去墓地。之后，对方从卡组选择1只怪兽攻击表示特殊召唤并进行战斗（玩家的战斗伤害为0）。回合结束时场上还存在怪兽的玩家获得决斗的胜利。其他的情况算平局。'),
(85602018, 'Last Will', '遗言状', '遺言状', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '只要该回合有怪兽从自己场上送入自己墓地就可以从卡组特殊召唤攻击力1500以下的1只怪兽到场上。'),
(3560069, 'Latency', '延迟天使', 'レイテンシ', 'Effect Monster', 'Cyberse', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡因效果从自己墓地加入手卡的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的①的效果特殊召唤的这张卡作为连接素材送去墓地的场合才能发动。自己从卡组抽1张。'),
(15667446, 'Latinum, Exarch of Dark World', '暗黑界的斗神 拉提纳', '暗黒界の闘神 ラチナ', 'Effect Monster', 'Fiend', 'DARK', 6, 1500, 2400, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。被对方的效果丢弃的场合，发动时以场上1只恶魔族怪兽为对象。那个场合，再让以下效果适用。 ●作为对象的恶魔族怪兽的攻击力上升500。'),
(42591472, 'Laughing Flower', '笑花', '笑う花', 'Normal Monster', 'Plant', 'EARTH', 2, 900, 500, '总是在笑着的花。如果持续听它的笑声的话，头脑就会变得混乱。'),
(80275707, 'Laughing Puffin', '小丑鸟 笑盈盈海鹦', '道化鳥ラフィンパフィン', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1000, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有表侧表示的魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把自己场上1只鸟兽族怪兽解放，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张表侧表示的卡回到持有者手卡。这个回合，自己不能把这个效果回到手卡的卡以及那些同名卡的效果发动。自己场上的怪兽只有鸟兽族怪兽的场合，这个效果在对方回合也能发动。'),
(35911108, 'Launcher Commander', '启动炮司令官', 'ランチャー・コマンダー', 'Effect Monster', 'Cyberse', 'EARTH', 4, 1700, 1200, '①：只要这张卡在怪兽区域存在，这张卡以外的自己场上的电子界族怪兽的攻击力·守备力上升300。 ②：1回合1次，把自己场上1只电子界族怪兽解放，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(87322377, 'Launcher Spider', 'TM-1火箭炮蜘蛛', 'TM－１ランチャースパイダー', 'Normal Monster', 'Machine', 'FIRE', 7, 2200, 2500, '开着火箭炮乱放一通，爆杀对手的机械蜘蛛。'),
(13171876, 'Laundry Dragonmaid', '龙女仆・清扫龙女', 'ドラゴンメイド・ラドリー', 'Effect Monster', 'Dragon', 'WATER', 2, 500, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己卡组上面把3张卡送去墓地。 ②：自己·对方的战斗阶段开始时才能发动。场上的这张卡回到手卡，从自己的手卡·墓地把1只7星「半龙女仆」怪兽特殊召唤。'),
(79371769, 'Laundry Trap', '清扫龙女的困境', 'ラドリートラップ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有怪兽召唤·特殊召唤的场合才能发动（同一连锁上最多1次）。从自己卡组上面把1张卡送去墓地。 ②：这张卡被效果从卡组送去墓地的场合，以「洗衣龙女困境」以外的这个回合被送去自己墓地的1张卡为对象才能发动。那张卡加入手卡。这个效果的发动后，直到下次的自己回合的结束时，自己不能作这个效果加入手卡的卡以及那些同名卡的效果的发动。'),
(20394040, 'Lava Battleguard', '野蛮人1号', 'バーバリアン１号', 'Effect Monster', 'Warrior', 'EARTH', 5, 1550, 1800, '①：自己场上的「野蛮人2号」每有1只，这张卡的攻击力上升500。'),
(41741922, 'Lava Dragon', '岩浆龙', 'ラヴァ・ドラゴン', 'Effect Monster', 'Dragon', 'FIRE', 4, 1600, 1200, '把自己场上表侧守备表示存在的这张卡解放发动。从自己的手卡以及墓地各把1只3星以下的龙族怪兽特殊召唤。'),
(102380, 'Lava Golem', '熔岩魔神・岩浆魔像', '溶岩魔神ラヴァ・ゴーレム', 'Effect Monster', 'Fiend', 'FIRE', 8, 3000, 2500, '这张卡不能通常召唤。把对方场上2只怪兽解放的场合可以在对方场上特殊召唤。把这张卡特殊召唤的回合，自己不能通常召唤。 ①：自己准备阶段发动。自己受到1000伤害。'),
(30303854, 'Laval Archer', '熔岩弓手', 'ラヴァル・アーチャー', 'Effect Monster', 'Pyro', 'FIRE', 4, 1000, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功的场合发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「熔岩」怪兽召唤。 ②：这张卡在墓地存在的场合，以自己场上1只炎属性怪兽为对象才能发动。那只怪兽破坏，这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个回合，自己不是炎属性怪兽不能特殊召唤。'),
(11834972, 'Laval Blaster', '熔岩炮击手', 'ラヴァル・ガンナー', 'Effect Monster', 'Warrior', 'FIRE', 4, 1200, 800, '这张卡召唤成功时，自己墓地有「熔岩炮击手」以外的名字带有「熔岩」的怪兽存在的场合，从自己卡组上面把最多5张卡送去墓地才能发动。这张卡的攻击力上升因为这个效果发动而送去墓地的名字带有「熔岩」的怪兽数量×200的数值。'),
(88958576, 'Laval Burner', '熔岩焚烧者', 'ラヴァルバーナー', 'Effect Monster', 'Pyro', 'FIRE', 5, 2100, 1000, '自己墓地有名字带有「熔岩」的怪兽3种类以上存在的场合，这张卡可以从手卡特殊召唤。'),
(38492752, 'Laval Cannon', '熔岩炮手', 'ラヴァル・キャノン', 'Effect Monster', 'Warrior', 'FIRE', 4, 1600, 900, '这张卡召唤·反转召唤成功时，可以选择从游戏中除外的1只自己的名字带有「熔岩」的怪兽特殊召唤。'),
(45439263, 'Laval Coatl', '熔岩风神翼龙', 'ラヴァル・コアトル', 'Tuner Monster', 'Pyro', 'FIRE', 2, 1300, 700, '自己墓地有名字带有「熔岩」的怪兽3种类以上存在的场合，这张卡可以从手卡特殊召唤。'),
(31632536, 'Laval Dual Slasher', '熔岩双杀手', 'ラヴァル・ツインスレイヤー', 'Synchro Monster', 'Warrior', 'FIRE', 5, 2400, 200, '调整＋调整以外的炎属性怪兽1只以上 自己墓地存在的名字带有「熔岩」的怪兽数量让这张卡得到以下效果。 ●2只以上：这张卡向守备表示怪兽攻击的场合，只有1次可以继续攻击。 ●3只以上：这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(15169262, 'Laval Forest Sprite', '熔岩炎树海的妖女', 'ラヴァル炎樹海の妖女', 'Tuner Monster', 'Pyro', 'FIRE', 2, 300, 200, '这张卡从场上送去墓地时，自己场上表侧表示存在的名字带有「熔岩」的怪兽的攻击力直到结束阶段时上升自己墓地存在的名字带有「熔岩」的怪兽数量×200的数值。'),
(14047624, 'Laval Judgment Lord', '熔岩裁决王', 'ラヴァルロード・ジャッジメント', 'Effect Monster', 'Warrior', 'FIRE', 7, 2700, 1800, '1回合1次，把自己墓地存在的1只名字带有「熔岩」的怪兽从游戏中除外才能发动。给与对方基本分1000分伤害。这个效果发动的回合，「熔岩裁决王」不能攻击宣言。'),
(8041569, 'Laval Lakeside Lady', '熔岩炎湖畔的淑女', 'ラヴァル炎湖畔の淑女', 'Tuner Monster', 'Pyro', 'FIRE', 3, 200, 200, '自己墓地有名字带有「熔岩」的怪兽3种类以上存在的场合，把自己墓地存在的这张卡和1只名字带有「熔岩」的怪兽从游戏中除外才能发动。选择对方场上盖放的1张卡破坏。'),
(123709, 'Laval Lancelord', '熔岩枪杖手', 'ラヴァル・ランスロッド', 'Effect Monster', 'Warrior', 'FIRE', 6, 2100, 200, '这张卡可以不用解放作召唤。这个方法召唤的这张卡在结束阶段时送去墓地。场上存在的这张卡被破坏送去墓地时，可以选择从游戏中除外的1只自己的炎属性怪兽加入手卡。'),
(46404281, 'Laval Magma Cannoneer', '熔岩人岩浆炮兵', 'ラヴァルのマグマ砲兵', 'Effect Monster', 'Pyro', 'FIRE', 4, 1700, 200, '从手卡把1只炎属性怪兽送去墓地发动。给与对方基本分500分伤害。这个效果1回合可以使用最多2次。'),
(89893715, 'Laval Miller', '推炎车的熔岩人', 'ラヴァルの炎車回し', 'Effect Monster', 'Pyro', 'FIRE', 3, 300, 400, '这张卡被战斗破坏送去墓地时，可以从自己卡组选择2只名字带有「熔岩」的怪兽送去墓地。'),
(89609515, 'Laval Phlogis', '熔岩燃素人', 'ラヴァル・フロギス', 'Effect Monster', 'Pyro', 'FIRE', 4, 1700, 800, '这张卡被送去墓地时，自己场上表侧表示存在的全部名字带有「熔岩」的怪兽的攻击力上升300。'),
(20374351, 'Laval Stennon', '熔岩星炮手', 'ラヴァル・ステライド', 'Synchro Monster', 'Pyro', 'FIRE', 7, 2700, 1800, '调整＋调整以外的炎属性怪兽1只以上 这张卡同调召唤成功时，自己把1张手卡送去墓地。这张卡成为卡的效果的对象时，可以把自己墓地存在的1只名字带有「熔岩」的怪兽从游戏中除外，那个发动无效并破坏。'),
(12986807, 'Laval the Greater', '熔岩大石人', 'ラヴァル・グレイター', 'Synchro Monster', 'Warrior', 'FIRE', 6, 2400, 800, '调整＋调整以外的炎属性怪兽1只以上 这张卡同调召唤成功时，自己把1张手卡送去墓地。这张卡被卡的效果破坏的场合，可以作为代替把自己墓地存在的1只名字带有「熔岩」的怪兽从游戏中除外。'),
(47658965, 'Laval Token', '红莲之炎壁', '紅蓮の炎壁', 'Token', 'Pyro', NULL, NULL, NULL, NULL, NULL),
(2407147, 'Laval Volcano Handmaiden', '熔岩炎火山的侍女', 'ラヴァル炎火山の侍女', 'Tuner Monster', 'Pyro', 'FIRE', 1, 100, 200, '①：这张卡被送去墓地时，自己墓地有「熔岩炎火山的侍女」以外的「熔岩」怪兽存在的场合才能发动。从卡组把1只「熔岩」怪兽送去墓地。'),
(52786469, 'Laval Warrior', '熔岩战士', 'ラヴァル・ウォリアー', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 500, '这张卡战斗破坏对方怪兽的场合自己墓地有名字带有「熔岩」的怪兽4种类以上存在的场合，给与对方基本分那次战斗破坏的怪兽的攻击力数值的伤害。'),
(34086406, 'Lavalval Chain', '熔岩谷锁链龙', 'ラヴァルバル・チェイン', 'XYZ Monster', 'Sea Serpent', 'FIRE', 4, 1800, 1000, '4星怪兽×2 ①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●从卡组选1张卡送去墓地。 ●从卡组选1只怪兽在卡组最上面放置。'),
(75991898, 'Lavalval Dragon', '熔岩谷龙', 'ラヴァルバル・ドラゴン', 'Synchro Monster', 'Dragon', 'FIRE', 5, 2000, 1100, '调整＋调整以外的炎属性怪兽1只以上 ①：让自己墓地2只「熔岩」怪兽回到卡组，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(8611007, 'Lavalval Dragun', '熔岩谷龙骑士', 'ラヴァルバル・ドラグーン', 'Synchro Monster', 'Dragon', 'FIRE', 6, 2500, 1200, '调整＋调整以外的炎属性怪兽1只以上 ①：1回合1次，自己主要阶段才能发动。从卡组把1只「熔岩」怪兽加入手卡。那之后，从手卡选1只「熔岩」怪兽送去墓地。'),
(12018201, 'Lavalval Exlord', '熔岩谷爆烈王', 'ラヴァルバル・エクスロード', 'Synchro Monster', 'Warrior', 'FIRE', 8, 2900, 200, '调整＋调整以外的炎属性怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：手卡·场上的怪兽的效果由对方发动时才能发动。那只怪兽破坏，给与对方1000伤害。 ②：同调召唤的这张卡被对方破坏的场合才能发动。从自己墓地选同调怪兽以外的最多3只守备力200的炎属性怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(3989465, 'Lavalval Ignis', '熔岩谷炎人', 'ラヴァルバル・イグニス', 'XYZ Monster', 'Warrior', 'FIRE', 3, 1800, 1400, '3星怪兽×2 这张卡进行战斗的伤害步骤时只有1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到结束阶段时上升500。'),
(67797569, 'Lavalval Salamander', '岩浆炎炎・沙罗曼蛇', 'ラヴァルバル・サラマンダー', 'Synchro Monster', 'Dragon', 'FIRE', 7, 2600, 200, '调整＋调整以外的炎属性怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤成功的场合才能发动。自己从卡组抽2张，那之后从手卡把包含炎属性怪兽的2张卡送去墓地。手卡没有炎属性怪兽的场合，手卡全部公开，回到卡组。 ②：1回合1次，从自己墓地把1只炎属性怪兽除外才能发动。选最多有自己场上的「熔岩」怪兽数量的对方场上的表侧表示怪兽变成里侧守备表示。'),
(64659851, 'Law of the Cosmos', '宇宙的法则', '宇宙の法則', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方可以从自身的手卡·卡组选1张陷阱卡在自身的魔法与陷阱区域盖放。盖放的场合，自己从卡组把1只「人造人-念力震慑者」特殊召唤。没盖放的场合，自己把1只「人造人-念力震慑者」或者1只有那个卡名记述的怪兽从卡组加入手卡。'),
(67468948, 'Layard the Liberator', '救济之莱亚德', '救済のレイヤード', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1500, '①：只要这张卡在怪兽区域存在，每次自己或者对方把反击陷阱卡发动，选除外的2只自己的天使族怪兽加入手卡。'),
(98349765, 'Layer 19: "Preventing the Invasion! The Pitch-Black Super Quantum!!"', '第19层 “袭来干涉！漆黑的超级量子士！！”', '第１９層『襲来干渉！漆黒の超量士！！』', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●以场上1只攻击表示怪兽为对象才能发动。那只怪兽变成守备表示。 ●自己场上有「超级量子」怪兽存在的场合才能发动。原本属性相同的怪兽不在自己场上存在的1只「超级量子」怪兽从卡组守备表示特殊召唤。 ●从卡组把1张「超级量子」陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(92435533, 'Lazion, the Timelord', '时械神 拉结恩', '時械神ラツィオン', 'Effect Monster', 'Fairy', 'FIRE', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。对方墓地的卡全部回到卡组。 ④：1回合1次，对方抽卡的场合发动。给与对方1000伤害。 ⑤：自己准备阶段发动。这张卡回到持有者卡组。'),
(50599453, 'Leafplace Plaice', '枯叶拟态鲽', '枯鰈葉リプレース', 'Effect Monster', 'Psychic', 'DARK', 3, -1, -1, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，对方墓地的卡数量比自己墓地的卡多的场合，自己准备阶段才能发动。这张卡特殊召唤。 ②：这张卡的攻击力·守备力上升对方墓地的卡数量×200。'),
(32126000, 'Learning Elf', '学习妖精', 'ラーニング・エルフ', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 1400, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。把持有把自身当作装备卡使用来装备效果的1张陷阱卡从卡组到自己场上盖放。 ②：这张卡从场上送去墓地的场合才能发动。自己抽1张。'),
(7127502, 'Lector Pendulum, the Dracoverlord', '龙魔王 至霸主载 灵摆', '竜魔王レクターP', 'Pendulum Effect Monster', 'Dragon', 'DARK', 4, 1950, NULL, '①：这张卡和灵摆怪兽进行战斗的伤害步骤开始时发动。那只怪兽和这张卡破坏。'),
(56256517, 'Ledger of Legerdemain', '预知存折', '予見通帳', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己卡组上面把3张卡里侧表示除外。这张卡的发动后第3次的自己准备阶段，这个效果除外的3张卡加入手卡。'),
(21893603, 'Lee the World Chalice Fairy', '星杯妖精 丽丝', '星杯の妖精リース', 'Effect Monster', 'Fairy', 'LIGHT', 2, 100, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「星杯」怪兽加入手卡。 ②：这张卡在墓地存在的场合，把自己的手卡·场上1只怪兽送去墓地才能发动。墓地的这张卡加入手卡。'),
(90263923, 'Leeching the Light', '闪光吸收', 'シャイニング・アブソーブ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只光属性怪兽发动。自己场上表侧攻击表示存在的全部怪兽的攻击力直到结束阶段时上升选择的怪兽的攻击力数值。'),
(7902349, 'Left Arm of the Forbidden One', '被封印者的左臂', '封印されし者の左腕', 'Normal Monster', 'Spellcaster', 'DARK', 1, 200, 300, '被封印的左腕。假若解开封印，能得无限之力。'),
(86541496, 'Left Arm Offering', '左臂的代价', '左腕の代償', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能把魔法·陷阱卡盖放。 ①：这张卡以外的自己手卡是2张以上的场合，把那些手卡全部除外才能发动。从卡组把1张魔法卡加入手卡。'),
(44519536, 'Left Leg of the Forbidden One', '被封印者的左足', '封印されし者の左足', 'Normal Monster', 'Spellcaster', 'DARK', 1, 200, 300, '被封印的左足。假若解开封印，能得无限之力。'),
(47840168, 'Left-Hand Shark', '左手鲨', 'レフトハンド・シャーク', 'Effect Monster', 'Fish', 'WATER', 3, 1300, 1500, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有「右手鲨」存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡从墓地的特殊召唤成功的场合发动。这张卡的等级变成4星。 ③：只用包含场上的这张卡的水属性怪兽为素材作超量召唤的怪兽得到以下效果。 ●这张卡不会被效果破坏。'),
(44935634, 'Lefty Driver', '左起子', 'レフティ・ドライバー', 'Effect Monster', 'Machine', 'EARTH', 2, 300, 100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。这张卡的等级直到回合结束时变成3星。 ②：把墓地的这张卡除外才能发动。从卡组把1只「右起子」加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(87010442, 'Legacy Hunter', '遗产猎人', 'レガシーハンター', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1500, '当这张卡战斗破坏里侧守备表示的怪兽并将其送去墓地时，对方随机将1张手卡弹回其卡组。'),
(25614410, 'Legacy of a HERO', '－英雄－之遗产', 'HEROの遺産', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「英雄的遗产」在1回合只能发动1张。 ①：让需以「英雄」怪兽为融合素材的2只融合怪兽从自己墓地回到额外卡组才能发动。自己从卡组抽3张。'),
(88851326, 'Legacy of the Duelist', '炽热的决斗者们', '熱き決闘者たち', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己怪兽的攻击宣言时，以对方场上1张魔法·陷阱卡为对象才能发动。那次攻击无效，作为对象的卡破坏。 ②：只要这张卡在魔法与陷阱区域存在，双方1回合只能有1张魔法·陷阱卡从手卡盖放，从额外卡组特殊召唤的怪兽在那个回合不能攻击。 ③：自己抽卡阶段的抽卡前才能发动。作为这个回合进行通常抽卡的代替，选自己墓地1只怪兽加入手卡。'),
(30461781, 'Legacy of Yata-Garasu', '八汰乌之骸', '八汰烏の骸', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从下面效果选择1个发动。 ●从自己卡组抽1张卡。 ●对方场上有灵魂怪兽表侧表示存在的场合才能发动。从自己卡组抽2张卡。'),
(89397517, 'Legend of Heart', '传说之心', 'レジェンド・オブ・ハート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「传说之心」在1回合只能发动1张。 ①：支付2000基本分，把自己场上1只战士族怪兽解放才能发动。自己的手卡·墓地的「传说之龙」魔法卡最多3种类除外，从自己的手卡·卡组·墓地选除外的种类数量的「传说的骑士」怪兽特殊召唤（同名卡最多1张）。'),
(28754338, 'Legendary Atlantean Tridon', '真海皇 特里冬', '真海皇 トライドン', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1600, 800, '把这张卡和自己场上1只海龙族怪兽解放才能发动。从手卡·卡组把1只「海皇龙 波塞德拉」特殊召唤。那之后，对方场上的全部怪兽的攻击力下降300。'),
(96458440, 'Legendary Black Belt', '传说之黑带', '伝説の黒帯', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的「格斗鼠 吱助」「武僧战士」「武僧大师」才能装备。装备怪兽因战斗破坏对方怪兽送去墓地时，给与对方基本分被破坏怪兽守备力数值的伤害。'),
(55343172, 'Legendary Dueling Field', '传说的决斗场', '伝説の決闘場', 'Normal Monster', 'Machine', 'EARTH', 5, NULL, 3000, '无论何时都相信所组建的卡组，无论何时都不背对敌人，奋战到最后一刻决不放弃的那些拥有勇气之人据传就在这里集结，此地是展开那一场场决出胜者与败者之仪式的战场。据说当自己和卡片之心凭借牵绊而团结，并赌上骄傲与灵魂迈出脚步之时，便能开拓出看不到尽头一直向前延伸的未来之大道。'),
(12324546, 'Legendary Ebon Steed', '漆黑的名马', '漆黒の名馬', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「六武众」的怪兽才能装备。装备怪兽的攻击力·守备力上升200。装备怪兽被破坏的场合，这张卡代替破坏。'),
(99747800, 'Legendary Fiend', '传说的恶魔', 'レジェンド・デビル', 'Effect Monster', 'Fiend', 'DARK', 6, 1500, 1800, '①：自己准备阶段发动。这张卡的攻击力上升700。'),
(90681088, 'Legendary Fire King Ponix', '真炎王 珀尼克斯', '真炎王 ポニクス', 'Effect Monster', 'Winged Beast', 'FIRE', 1, 500, 200, '这个卡名的①②③的效果1回合各能使用1次。 ①：原本属性是炎属性的自己怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「炎王」魔法·陷阱卡加入手卡。 ③：这张卡被破坏送去墓地的场合，下次的准备阶段发动。墓地的这张卡加入手卡。'),
(60258960, 'Legendary Flame Lord', '传说的爆炎使', '伝説の爆炎使い', 'Ritual Effect Monster', 'Spellcaster', 'FIRE', 7, 2400, 2000, '通过仪式魔法卡「灼热之试练」特殊召唤。特殊召唤时，必须以场上和/或手卡中合计7颗星以上的怪兽作为祭品。自己与对方每发动1次魔法，就在这张卡上放置1个魔力指示物。从这张卡上每除去3个魔力指示物，即可破坏场上除这张卡以外的所有怪兽。'),
(25773409, 'Legendary Jujitsu Master', '传说的柔术家', '伝説の柔術家', 'Effect Monster', 'Rock', 'EARTH', 3, 1300, 1800, '与守备表示的这张卡进行战斗的怪兽在伤害步骤终了时弹回其持有者的卡组的最上面。'),
(85800949, 'Legendary Knight Critias', '传说的骑士 克里底亚', '伝説の騎士 クリティウス', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 1800, '这张卡不能通常召唤。「传说之心」的效果才能特殊召唤。 ①：这张卡特殊召唤成功时，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张表侧表示的魔法·陷阱卡除外。 ②：这张卡被选择作为攻击对象时，以自己墓地1张陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(84565800, 'Legendary Knight Hermos', '传说的骑士 赫谟', '伝説の騎士 ヘルモス', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 1800, '这张卡不能通常召唤。「传说之心」的效果才能特殊召唤。 ①：这张卡特殊召唤成功时，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张表侧表示的魔法·陷阱卡除外。 ②：1回合1次，这张卡被选择作为攻击对象时，以自己墓地1只效果怪兽为对象才能发动。这张卡直到下次的自己回合的结束阶段当作和那只墓地的怪兽同名卡使用，得到相同效果。'),
(80019195, 'Legendary Knight Timaeus', '传说的骑士 蒂迈欧', '伝説の騎士 ティマイオス', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 1800, '这张卡不能通常召唤。「传说之心」的效果才能特殊召唤。 ①：这张卡特殊召唤成功时，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张表侧表示的魔法·陷阱卡除外。 ②：这张卡被选择作为攻击对象时，以自己墓地1张魔法卡为对象才能发动。那张卡在自己场上盖放。'),
(70634245, 'Legendary Lord Six Samurai - Enishi', '真魔六武众－缘', '真魔六武衆－エニシ', 'Synchro Monster', 'Warrior', 'LIGHT', 6, 1700, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，把自己墓地的「六武众」怪兽任意数量除外，以那个数量的对方场上的怪兽为对象才能发动。那些怪兽回到手卡。 ②：自己场上的战士族怪兽的攻击力·守备力只在战斗阶段内上升500。 ③：这张卡被送去墓地的场合才能发动。自己的除外状态的1只「六武众」怪兽特殊召唤。'),
(42209438, 'Legendary Lord Six Samurai - Kizan', '真魔六武众－鬼斩', '真魔六武衆－キザン', 'Synchro Monster', 'Warrior', 'EARTH', 6, 1800, 800, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的「六武众」怪兽的攻击力·守备力只在战斗阶段内上升600。 ②：对方主要阶段，从自己墓地把1张「六武式」卡除外，以场上1张卡为对象才能发动。那张卡破坏。 ③：自己场上有「六武众」怪兽2只以上存在的场合才能发动。这张卡从墓地特殊召唤。'),
(34235530, 'Legendary Lord Six Samurai - Shi En', '真魔六武众－紫焰', '真魔六武衆－シエン', 'Synchro Monster', 'Warrior', 'DARK', 6, 2500, 1900, '战士族调整＋调整以外的「六武众」怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己的卡组·墓地把1只「六武众」怪兽或「紫炎」效果怪兽加入手卡。 ②：1回合1次，对方把怪兽的效果发动时才能发动。那个发动无效并破坏。 ③：场上的这张卡被战斗·效果破坏的场合，可以作为代替把自己场上1只怪兽破坏。'),
(12338068, 'Legendary Maju Garzett', '真魔兽 加泽特', '真魔獣 ガーゼット', 'Effect Monster', 'Fiend', 'DARK', 8, NULL, NULL, '这张卡不能通常召唤。把自己场上的怪兽全部解放的场合才能特殊召唤。 ①：这张卡的攻击力变成因为这张卡特殊召唤而解放的怪兽的原本攻击力合计数值。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(15327215, 'Legendary Secret of the Six Samurai', '六武众之真影', '六武衆の真影', 'Effect Monster', 'Warrior', 'DARK', 4, 500, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：自己对「影六武众」怪兽的召唤·特殊召唤成功时才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，从自己墓地把1只4星以下的「六武众」怪兽除外才能发动。直到回合结束时，这张卡的属性·等级·攻击力·守备力变成和除外的那只怪兽相同。'),
(75116619, 'Legendary Six Samurai - Enishi', '真六武众－缘', '真六武衆－エニシ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 700, '自己场上有「真六武众-缘」以外的名字带有「六武众」的怪兽表侧表示存在的场合，1回合1次，可以把自己墓地存在的2只名字带有「六武众」的怪兽从游戏中除外，选择场上表侧表示存在的1只怪兽回到手卡。这个效果在对方回合也能发动。此外，自己场上有「真六武众-缘」以外的名字带有「六武众」的怪兽表侧表示2只以上存在的场合，这张卡的攻击力·守备力上升500。'),
(2511717, 'Legendary Six Samurai - Kageki', '真六武众－影木', '真六武衆－カゲキ', 'Effect Monster', 'Warrior', 'WIND', 3, 200, 2000, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的「六武众」怪兽特殊召唤。 ②：自己场上有「真六武众-阴鬼」以外的「六武众」怪兽存在的场合，这张卡的攻击力上升1500。'),
(49721904, 'Legendary Six Samurai - Kizan', '真六武众－鬼斩', '真六武衆－キザン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 500, '①：自己场上有「真六武众-辉斩」以外的「六武众」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己场上有这张卡以外的「六武众」怪兽2只以上存在的场合，这张卡的攻击力·守备力上升300。'),
(74094021, 'Legendary Six Samurai - Mizuho', '真六武众－瑞穗', '真六武衆－ミズホ', 'Effect Monster', 'Warrior', 'FIRE', 3, 1600, 1000, '自己场上有「真六武众-竹刀」表侧表示存在的场合，这张卡可以从手卡特殊召唤。此外，1回合1次，可以把这张卡以外的自己场上存在的1只名字带有「六武众」的怪兽解放，选择场上存在的1张卡破坏。'),
(29981921, 'Legendary Six Samurai - Shi En', '真六武众－紫焰', '真六武衆－シエン', 'Synchro Monster', 'Warrior', 'DARK', 5, 2500, 1400, '战士族调整＋调整以外的「六武众」怪兽1只以上 ①：1回合1次，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把自己场上1只「六武众」怪兽破坏。'),
(48505422, 'Legendary Six Samurai - Shinai', '真六武众－志奈', '真六武衆－シナイ', 'Effect Monster', 'Warrior', 'WATER', 3, 1500, 1500, '自己场上有「真六武众-瑞穂」表侧表示存在的场合，这张卡可以从手卡特殊召唤。场上存在的这张卡被解放的场合，选择自己墓地存在的「真六武众-竹刀」以外的1只名字带有「六武众」的怪兽加入手卡。'),
(61854111, 'Legendary Sword', '传说之剑', '伝説の剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族才能装备。1只装备怪兽的攻击力和守备力上升300。'),
(69320362, 'Legendary Wind-Up Key', '传说的发条', '伝説のゼンマイ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「发条」的怪兽全部变成里侧守备表示。'),
(12472242, 'Leghul', '百足虫', 'レッグル', 'Effect Monster', 'Insect', 'EARTH', 1, 300, 350, '这张卡可以直接攻击对方玩家。'),
(25280974, 'Legion the Fiend Jester', '魔道小丑 利真', '魔道化リジョン', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1300, 1500, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只魔法师族怪兽表侧攻击表示上级召唤。 ②：这张卡从场上送去墓地的场合才能发动。从自己的卡组·墓地选1只魔法师族通常怪兽加入手卡。'),
(62543393, 'Lekunga', '裂蕈牙', 'レクンガ', 'Effect Monster', 'Plant', 'WATER', 4, 1700, 500, '从自己墓地里除外2只水属性怪兽，在自己场上以攻击表示特殊召唤1只「裂蕈牙衍生物」（水·2星·植物族·攻/守700）。'),
(62543394, 'Lekunga Token', '裂蕈牙', 'レクンガ', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(34318086, 'Lemon Magician Girl', '柠檬魔术少女', 'レモン・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 800, 600, '①：1回合1次，把「柠檬魔术少女」以外的自己场上1只「魔术少女」怪兽解放才能发动。从卡组把1只魔法师族怪兽加入手卡。 ②：1回合1次，这张卡被选择作为攻击对象的场合才能发动。从手卡把1只魔法师族怪兽效果无效特殊召唤。那之后，攻击对象转移为那只怪兽，攻击怪兽的攻击力变成一半。'),
(34103656, 'Lemuria, the Forgotten City', '忘却之都 利莫里亚', '忘却の都 レミューリア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的卡名当作「海」使用。只要这张卡在场上存在，场上的水属性怪兽的攻击力·守备力上升200。此外，1回合1次，自己的主要阶段时才能发动。只要这张卡在场上存在，自己场上的水属性怪兽的等级直到结束阶段时上升和自己场上的水属性怪兽数量相同数值。'),
(70298454, 'Leng Ling', '比翼连鳞', '比翼レンリン', 'Union Effect Monster', 'Dragon', 'DARK', 3, 1500, NULL, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽的原本攻击力变成1000，同1次的战斗阶段中可以作2次攻击。'),
(4392470, 'Leo Wizard', '狮子男巫', 'レオ・ウィザード', 'Normal Monster', 'Spellcaster', 'EARTH', 5, 1350, 1200, '披着黑披风的魔术师。其正体是只能说话的狮子。'),
(55423549, 'Leo Wizard the Dark Fiend', '黑魔族－狮子男巫', '黒き魔族－レオ・ウィザード', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1350, 1200, '这个卡名的③的效果1回合只能使用1次。 ①：双方在原本等级是4星以下而攻击力或守备力比1350大的怪兽从手卡召唤的场合，必须把1只怪兽解放来上级召唤。 ②：这张卡和光属性怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只攻击力1350的怪兽加入手卡。'),
(8561192, 'Leo, the Keeper of the Sacred Tree', '神树的守护兽－牙王', '神樹の守護獣－牙王', 'Synchro Monster', 'Beast', 'EARTH', 10, 3100, 1900, '调整＋调整以外的怪兽1只以上 这张卡在自己的主要阶段2以外不会成为对方的卡的效果的对象。'),
(57201737, 'Leodrake''s Mane', '狮面草的鬃毛', 'ガオドレイクのタテガミ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「自然」的怪兽发动。选择的怪兽的攻击力直到结束阶段时变成3000，效果无效化。'),
(10538007, 'Leogun', '狮子王', 'レオグン', 'Normal Monster', 'Beast', 'EARTH', 5, 1750, 1550, '浑身百兽之王般漂亮的鬃毛，身体也很庞大。'),
(98225108, 'Leotaur', '人狮兽', 'レオンタウロス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1500, 1600, '①：这张卡和通常怪兽以外的怪兽进行战斗的伤害步骤内，这张卡的攻击力上升500。'),
(47226949, 'Leotron', '雄狮创机', 'ライドロン', 'Normal Monster', 'Cyberse', 'EARTH', 4, 2000, NULL, '具备高适应能力的电子兽。领地意识很强。'),
(49922726, 'Leraje the God of Archery', '弓神 勒莱耶', '弓神レライエ', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。这张卡的攻击力直到回合结束时上升自己墓地的怪兽的种族种类×100。 ②：以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的守备力下降这张卡的攻击力数值。这个效果让那只怪兽的守备力变成0的场合，再把那只怪兽破坏。这个效果的发动后，直到回合结束时这张卡不能攻击。'),
(55444629, 'Lesser Dragon', '下级龙', 'レッサー・ドラゴン', 'Normal Monster', 'Dragon', 'WIND', 4, 1200, 1000, '不怎么强，连吐息攻击都不会的低级龙。'),
(16475472, 'Lesser Fiend', '下位恶魔', 'レッサー・デーモン', 'Effect Monster', 'Fiend', 'DARK', 5, 2100, 1000, '只要这张卡在场上表侧表示存在，这张卡战斗破坏的怪兽不送去墓地从游戏中除外。'),
(38625110, 'Let''s Go Together', '晨曦映雪白皎皎 笑语成霜共行脚', '夙めてはしろ 二人ではしろ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的场上（表侧表示）·墓地·除外状态的其中每种都没有「清晨一片雪白色 两人一同雪中行」存在的场合，从自己卡组上面把7张卡里侧除外才能发动。对方必须从自身的卡组上面·额外卡组把合计7张卡里侧除外。'),
(34950192, 'Lev Shaddoll Fusion', '心影依结合', '凍てし心が映す神影', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是「影依」怪兽不能从额外卡组特殊召唤。 ①：作为这张卡的发动时的效果处理，从额外卡组把1只融合怪兽送去墓地。 ②：把自己场上1只融合怪兽解放才能发动。和那只怪兽属性不同的1只「影依」融合怪兽从额外卡组当作融合召唤作特殊召唤。这个效果特殊召唤的怪兽的攻击力变成0。'),
(84397023, 'Level Conversion Lab', '等级变换实验室', 'レベル変換実験室', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己手卡1张怪兽卡给对方看，投掷1次骰子。出现的数目是1的场合，选择的怪兽送去墓地。出现的数目是2至6的场合，这个回合的结束阶段前，这只怪兽的等级变为投掷的数目。'),
(90500169, 'Level Down!?', '等级下降！？', 'レベルダウン！？', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只持有「LV」的怪兽发动。选择的卡回到原本的持有者卡组，从持有者墓地把1只比那张卡的「LV」低的同名怪兽无视召唤条件在持有者场上特殊召唤。'),
(57421866, 'Level Eater', '等级偷窃虫', 'レベル・スティーラー', 'Effect Monster', 'Insect', 'DARK', 1, 600, NULL, '①：这张卡只要在怪兽区域存在，不能为上级召唤以外而解放。 ②：这张卡在墓地存在的场合，以自己场上1只5星以上的怪兽为对象才能发动。那只怪兽的等级下降1星，这张卡从墓地特殊召唤。'),
(37198732, 'Level Lifter', '等级大师', 'レベル・マイスター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1只怪兽送去墓地，选择自己场上表侧表示存在的最多2只怪兽才能发动。选择的怪兽的等级直到结束阶段时变成和为这张卡发动而送去墓地的怪兽的原本等级相同。'),
(54976796, 'Level Limit - Area A', '等级限制A地区', 'レベル制限A地区', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上表侧表示存在的3星以下怪兽全部变成攻击表示。'),
(3136426, 'Level Limit - Area B', '等级限制B地区', 'レベル制限B地区', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上的4星以上的怪兽变成守备表示。'),
(61850482, 'Level Modulation', '等级调整', 'レベル調整', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方抽2张卡。自己墓地存在的名字中带有「LV」的1只怪兽，无视召唤条件特殊召唤。这个效果特殊召唤的怪兽，这个回合不能攻击也不能效果发动以及适用。'),
(86133013, 'Level Resist Wall', '等级抗蚀墙', 'レベル・レジストウォール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽被战斗或者对方的效果破坏的场合，以那1只怪兽为对象才能发动。等级合计直到变成和那只怪兽相同为止，从卡组选怪兽任意数量守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(86223870, 'Level Retuner', '等级重调', 'レベル・リチューナー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只怪兽的等级下降最多2星。'),
(74741494, 'Level Tuning', '能力调整', '能力調整', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的全部怪兽的等级直到结束阶段时下降1星。'),
(25290459, 'Level Up!', '等级上升！', 'レベルアップ！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把场上表侧表示存在的名字有「LV」的怪兽送去墓地发动。那张卡上面记述的怪兽，无视召唤条件从手卡·卡组特殊召唤。'),
(97385276, 'Level Warrior', '等级战士', 'レベル・ウォリアー', 'Effect Monster', 'Warrior', 'LIGHT', 3, 300, 600, '场上没有怪兽存在的场合，这张卡可以作为2星怪兽从手卡召唤。对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以作为4星怪兽从手卡特殊召唤。'),
(37721209, 'Levia-Dragon - Daedalus', '海龙-泰达路斯', '海竜－ダイダロス', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2600, 1500, '①：把自己场上1张表侧表示的「海」送去墓地才能发动。这张卡以外的场上的卡全部破坏。'),
(95992081, 'Leviair the Sea Dragon', '虚空海龙 利维埃尔', '虚空海竜リヴァイエール', 'XYZ Monster', 'Aqua', 'WIND', 3, 1800, 1600, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己或对方的除外状态的1只4星以下的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(33113958, 'LeVirtue Dragon', '海善龙', 'リヴァーチュ・ドラゴン', 'XYZ Monster', 'Sea Serpent', 'WATER', 3, 2000, NULL, '3星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「善德激流弹」加入手卡。 ②：可以从以下效果选择1个发动。 ●自己场上1个超量素材取除。那之后，从自己墓地把「海善龙」以外的1只鱼族·海龙族·水族怪兽加入手卡。 ●以场上2只超量怪兽为对象才能发动。那之内的1只的1个超量素材作为另1只的超量素材。'),
(39752820, 'Lib the World Key Blademaster', '星键士 利伊布', '星鍵士リイヴ', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2000, NULL, '怪兽2只 这张卡在自己墓地有「星遗物」卡存在的场合才能连接召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组选1张「星遗物」魔法·陷阱卡在自己场上盖放。这个回合，自己墓地没有「星遗物」怪兽存在的场合，那张卡不能发动。 ②：连接召唤的这张卡作为连接素材送去墓地的场合才能发动。选场上1张卡回到持有者卡组。'),
(24643913, 'Liberator Eto', '叛革者 哀陀', '叛逆者エト', 'Effect Monster', 'Reptile', 'DARK', 8, 4000, NULL, '这张卡不能通常召唤。「叛逆者 埃图」1回合1次在持有以下效果的怪兽卡在对方的场上或墓地存在，把基本分支付一半的场合才能从手卡·墓地特殊召唤。 ●需在有效果发动时连锁并在手卡或怪兽区域发动的效果 ①：这张卡的特殊召唤不会被无效化。 ②：这张卡只要在怪兽区域存在，不能作为融合·同调·超量·连接召唤的素材，自己回合内不受对方场上发动的怪兽的效果影响。'),
(72022087, 'Liberty at Last!', '自由解放', '自由解放', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己怪兽被战斗破坏送去墓地时，以场上2只表侧表示怪兽为对象才能发动。那些表侧表示怪兽回到持有者卡组。'),
(62957424, 'Libic, Malebranche of the Burning Abyss', '彼岸恶鬼 利比欧谷', '彼岸の悪鬼 リビオッコ', 'Effect Monster', 'Fiend', 'DARK', 3, 1300, 700, '「彼岸的恶鬼 利比科克」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合才能发动。从手卡把1只恶魔族·暗属性·3星怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(19516687, 'Libromancer Agent', '书灵师·代理人', 'リブロマンサー・エージェント', 'Effect Monster', 'Warrior', 'EARTH', 6, 2000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：以「书灵师·代理人」以外的自己墓地1张「书灵师」卡为对象才能发动。那张卡加入手卡。这个效果把魔法·陷阱卡加入手卡的场合，再选自己1张手卡回到卡组最下面。'),
(41085464, 'Libromancer Bonded', '书灵师再崛起', 'リブロマンサー・リライジング', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「书灵师」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「书灵师」仪式怪兽仪式召唤。这个效果使用场上的「书灵师·炽火燃点侠」作仪式召唤的「书灵师·炽火爆裂侠」不会被效果破坏，不能用效果除外。'),
(88083109, 'Libromancer Displaced', '书灵师波及', 'リブロマンサー・アフェクテッド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「书灵师」怪兽和对方场上1只怪兽为对象才能发动。那只自己怪兽回到持有者手卡，得到那只对方怪兽的控制权。以仪式怪兽以外的自己怪兽为对象把这张卡发动的场合，这个效果得到控制权的怪兽在结束阶段回到持有者手卡。');